```openscad
// Stand for 4 standard 1 cm spectrophotometer cuvettes
// Units: mm. Print orientation: base on z = 0, pockets open upward.

// ---------- Block ----------
block_x = 80;      // block length (X)
block_y = 26;      // block width (Y)
block_h = 25;      // block height (Z)

// ---------- Pockets ----------
pocket_n     = 4;      // number of cuvette pockets
pocket_w     = 13.2;   // pocket size in X and Y (square)
pocket_depth = 20;     // pocket depth from top face
pocket_pitch = 18.2;   // centre-to-centre spacing along X
floor_t      = block_h - pocket_depth; // 5 mm solid floor under pockets

eps = 0.5;             // cutter overshoot past top face

// X position of the first pocket so the row is centred on the block
first_x = -(pocket_n - 1) * pocket_pitch / 2;

difference() {
    // Main block, centred in X/Y, sitting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_h]);

    // Row of square cuvette pockets
    for (i = [0 : pocket_n - 1])
        translate([first_x + i * pocket_pitch - pocket_w / 2,
                   -pocket_w / 2,
                   floor_t])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
}
```

