// Stand for 4 standard 1 cm spectrophotometer cuvettes
// Print orientation: base on XY plane (z = 0), pockets open upward (+Z)

$fn = 64;

// ---- Block dimensions ----
block_x = 80;      // block length along X (mm)
block_y = 26;      // block width along Y (mm)
block_z = 28;      // block height along Z (mm)

// ---- Pocket dimensions ----
pocket_w     = 13.2;  // pocket size in X and Y (square, mm)
pocket_depth = 23;    // pocket depth from top face (mm)
pocket_pitch = 18.2;  // centre-to-centre spacing along X (mm)
pocket_count = 4;     // number of pockets

// ---- Derived ----
floor_t   = block_z - pocket_depth;              // floor thickness under pockets (5 mm)
row_start = -(pocket_count - 1) * pocket_pitch / 2; // X of first pocket centre
overcut   = 0.5;                                  // extension past top face for clean cut

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Row of square cuvette pockets, centred on block
    for (i = [0 : pocket_count - 1]) {
        translate([row_start + i * pocket_pitch - pocket_w / 2,
                   -pocket_w / 2,
                   floor_t])
            cube([pocket_w, pocket_w, pocket_depth + overcut]);
    }
}
