// Horizontal pipette rest
// Print orientation: base plate on the bed, uprights building up in +Z

$fn = 96;

// ---- Base plate ----
base_len   = 160;   // plate length along X (mm)
base_wid   = 30;    // plate width along Y (mm)
base_thk   = 4;     // plate thickness along Z (mm)

// ---- Uprights ----
up_thk     = 10;    // upright thickness along X (mm)
up_h       = 40;    // upright height from bed, z = 0 to 40 (mm)

// ---- Cradle notch ----
notch_r    = 8;     // semicircular notch radius (mm)
notch_z    = up_h;  // notch centre height, on the top edge (mm)

eps        = 0.5;   // overshoot for clean cuts (mm)

module upright(x_center) {
    difference() {
        translate([x_center - up_thk/2, -base_wid/2, 0])
            cube([up_thk, base_wid, up_h]);
        // Cradle: cylinder along X centred at y = 0, z = top edge
        translate([x_center - up_thk/2 - eps, 0, notch_z])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_thk + 2*eps);
    }
}

union() {
    // Base plate centred on origin
    translate([-base_len/2, -base_wid/2, 0])
        cube([base_len, base_wid, base_thk]);

    // Uprights flush with each end of the plate
    for (s = [-1, 1])
        upright(s * (base_len/2 - up_thk/2));
}
