```openscad
// Horizontal pipette rest
// Print orientation: base plate on the bed (z = 0), uprights build upward (+Z)

// ---------- Parameters ----------
base_len      = 120;   // base plate length along X
base_wid      = 40;    // base plate width along Y
base_thk      = 6;     // base plate thickness (z = 0 to 6)

upright_thk   = 8;     // upright block thickness along X
upright_h     = 30;    // upright height (z = 0 to 30)

cradle_r      = 9;     // radius of semicircular cradle notch
cradle_z      = upright_h; // notch centre height (on top edge)

eps           = 0.5;   // overcut so cutting faces are not coplanar
$fn           = 128;   // smoothness of curved shapes

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X and Y
        translate([-base_len/2, -base_wid/2, 0])
            cube([base_len, base_wid, base_thk]);

        // Two uprights, flush with each end of the plate
        for (sx = [-1, 1])
            translate([sx > 0 ? base_len/2 - upright_thk : -base_len/2,
                       -base_wid/2, 0])
                cube([upright_thk, base_wid, upright_h]);
    }

    // Cradle notches: cylinder along X, centred at y = 0, z = 30
    for (sx = [-1, 1])
        translate([sx > 0 ? base_len/2 - upright_thk - eps
                          : -base_len/2 - eps,
                   0, cradle_z])
            rotate([0, 90, 0])
                cylinder(r = cradle_r, h = upright_thk + 2*eps);
}
```

