$fn = 96;

// ---------- Dimensions (mm) ----------
base_len      = 140;   // base plate length (X)
base_wid      = 40;    // base plate width (Y)
base_thk      = 4;     // base plate thickness (Z)

upright_thk   = 10;    // upright block thickness (X)
upright_wid   = base_wid; // upright width (Y), same as plate
upright_h     = 40;    // upright total height from bed (Z)

cradle_r      = 8;     // cradle notch radius
cradle_y      = 0;     // cradle centre Y
cradle_z      = upright_h; // cradle centre Z (on top edge)

eps           = 0.5;   // cutter overshoot past faces

// ---------- Model ----------
difference() {
    union() {
        // Base plate
        translate([-base_len/2, -base_wid/2, 0])
            cube([base_len, base_wid, base_thk]);

        // Uprights, flush with each end of the plate
        for (s = [-1, 1])
            translate([s > 0 ? base_len/2 - upright_thk : -base_len/2,
                       -upright_wid/2, 0])
                cube([upright_thk, upright_wid, upright_h]);
    }

    // Semicircular cradle notches through each upright along X
    for (s = [-1, 1]) {
        x0 = s > 0 ? base_len/2 - upright_thk : -base_len/2;
        translate([x0 - eps, cradle_y, cradle_z])
            rotate([0, 90, 0])
                cylinder(r = cradle_r, h = upright_thk + 2*eps);
    }
}
