```openscad
// Flat hex-cap wrench for reagent bottles
// Print orientation: flat on bed, z = 0 to plate_t

// ---------------- Parameters ----------------
plate_t      = 6;     // plate thickness (Z)
head_d       = 55;    // round head diameter, centred on origin
handle_w     = 14;    // handle width (Y)
handle_x0    = 0;     // handle start (X)
handle_x1    = 100;   // handle end (X)
hex_af       = 32;    // hex hole size across flats
cut_ext      = 0.5;   // extension of cutters past faces

hex_R = (hex_af / 2) / cos(30);   // hex circumradius (corner distance)

$fn = 128;

// ---------------- Model ----------------
difference() {
    union() {
        // Round head
        cylinder(d = head_d, h = plate_t);

        // Straight handle
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_x1 - handle_x0, handle_w, plate_t]);
    }

    // Hexagonal hole: corners on X axis -> flats parallel to X axis
    translate([0, 0, -cut_ext])
        linear_extrude(height = plate_t + 2 * cut_ext)
            polygon([for (i = [0:5]) [hex_R * cos(60 * i), hex_R * sin(60 * i)]]);
}
```

