```openscad
// Hex key organiser block
// Print orientation: block standing on z = 0, pockets open at the top (+Z)

// ---------------- Parameters ----------------
block_len   = 90;     // block length along X (mm)
block_wid   = 16;     // block width along Y (mm)
block_hgt   = 25;     // block height along Z (mm)

pocket_depth = 12;    // hex pocket depth from top face (mm)
pocket_pitch = 14;    // centre-to-centre spacing of pockets along X (mm)
hex_flats    = [1.9, 2.4, 2.9, 3.4, 4.4, 5.4]; // across-flats sizes, -X to +X (mm)

eps = 0.5;            // extra length so cutters pass through the top face (mm)

// ---------------- Derived ----------------
n_pockets = len(hex_flats);

// Circumradius of a regular hexagon from its across-flats size
function hex_r(f) = f / sqrt(3);

// X position of pocket i, pattern centred on the block
function pocket_x(i) = (i - (n_pockets - 1) / 2) * pocket_pitch;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_hgt]);

    // Hexagonal pockets from the top face.
    // cylinder with $fn = 6 places vertices on the +/-X axis,
    // so two flats are parallel to the X axis.
    for (i = [0 : n_pockets - 1])
        translate([pocket_x(i), 0, block_hgt - pocket_depth])
            cylinder(h = pocket_depth + eps, r = hex_r(hex_flats[i]), $fn = 6);
}
```

