// Flat spacer ring - raises an instrument off the bench
// Print orientation: lying flat on the bed, z = 0 up to thickness

// ---------- Dimensions (mm) ----------
thickness      = 5;     // ring thickness (Z)
outer_d        = 60;    // outer diameter
inner_d        = 32;    // inner (bore) diameter
hole_d         = 4.5;   // through-hole diameter
hole_count     = 8;     // number of through-holes
hole_circle_d  = 46;    // pitch circle diameter for holes
hole_start_ang = 0;     // first hole on +X axis (degrees)

eps            = 0.5;   // cutter overshoot past faces
fn_ring        = 128;   // facets for ring outlines
fn_hole        = 64;    // facets for small holes

// ---------- Model ----------
difference() {
    // Outer disc
    cylinder(d = outer_d, h = thickness, $fn = fn_ring);

    // Central bore
    translate([0, 0, -eps])
        cylinder(d = inner_d, h = thickness + 2 * eps, $fn = fn_ring);

    // Bolt-circle through-holes
    for (i = [0 : hole_count - 1]) {
        ang = hole_start_ang + i * 360 / hole_count;
        translate([hole_circle_d / 2 * cos(ang),
                   hole_circle_d / 2 * sin(ang),
                   -eps])
            cylinder(d = hole_d, h = thickness + 2 * eps, $fn = fn_hole);
    }
}
