// Microplate riser
// Units: mm. Prints upright: legs on the bed at z = 0, plate on top.

// ---------------- Parameters ----------------
plate_x      = 130;   // top plate length (X)
plate_y      = 100;   // top plate width (Y)
plate_t      = 4;     // top plate thickness
top_z        = 60;    // height of top face of plate

leg_size     = 12;    // square leg cross-section (X and Y)

window_x     = 86;    // central window length (X)
window_y     = 56;    // central window width (Y)

eps          = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------------- Derived ----------------
plate_bottom_z = top_z - plate_t;   // underside of plate (56)
leg_h          = plate_bottom_z;    // legs run from z=0 to plate underside

// ---------------- Model ----------------
union() {
    // Top plate with central window
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bottom_z])
            cube([plate_x, plate_y, plate_t]);

        translate([-window_x/2, -window_y/2, plate_bottom_z - eps])
            cube([window_x, window_y, plate_t + 2*eps]);
    }

    // Four corner legs, flush with the plate's outer edges.
    // Legs overlap the plate by eps so the union is one solid.
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([
            sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
            sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
            0
        ])
            cube([leg_size, leg_size, leg_h + eps]);
    }
}
