union() {
    // Top plate with central window
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bottom_z])
            cube([plate_x, plate_y, plate_t]);
        translate([-window_x/2, -window_y/2, plate_bottom_z - eps])
            cube([window_x, window_y, plate_t + 2*eps]);
    }

    // Four corner legs, flush with plate outer edges
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([
            sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
            sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
            0
        ])
            // slight overlap into the plate so the union is one solid
            cube([leg_size, leg_size, leg_h + eps]);
