// Wall mounting strip with countersunk screw holes
// Print orientation: flat on bed, countersinks facing up (+Z)

$fn = 96;

// ---- Bar dimensions ----
bar_len   = 100;   // length along X (mm)
bar_wid   = 24;    // width along Y (mm)
bar_thk   = 5;     // thickness along Z (mm)

// ---- Screw holes ----
hole_count   = 3;     // number of screw holes
hole_pitch   = 40;    // centre-to-centre spacing along X (mm)
hole_d       = 5.5;   // through-hole diameter (mm)
csk_d        = 11;    // countersink diameter at top surface (mm)
csk_angle    = 90;    // included countersink angle (deg)

// ---- Derived values ----
csk_depth = (csk_d - hole_d) / 2 / tan(csk_angle / 2); // cone depth from top face
eps       = 0.5;      // overshoot past cut faces
csk_d_top = csk_d + 2 * eps * tan(csk_angle / 2);       // cone diameter at overshoot height

difference() {
    // Flat bar, centred in X/Y, resting on z = 0
    translate([-bar_len / 2, -bar_wid / 2, 0])
        cube([bar_len, bar_wid, bar_thk]);

    // Screw holes along X at y = 0, centred on the bar
    for (i = [0 : hole_count - 1]) {
        x = (i - (hole_count - 1) / 2) * hole_pitch;
        translate([x, 0, 0]) {
            // Through-hole
            translate([0, 0, -eps])
                cylinder(h = bar_thk + 2 * eps, d = hole_d);
            // 90-degree countersink on the top face
            translate([0, 0, bar_thk - csk_depth])
                cylinder(h = csk_depth + eps, d1 = hole_d, d2 = csk_d_top);
        }
    }
}
