// Wall mounting strip with two countersunk screw holes
// Print orientation: flat on bed, countersinks facing up (+Z)

// ---------------- Parameters ----------------
bar_length   = 60;    // bar length along X (mm)
bar_width    = 24;    // bar width along Y (mm)
bar_thick    = 4;     // bar thickness along Z (mm)

hole_count   = 2;     // number of screw holes
hole_pitch   = 30;    // centre-to-centre hole spacing along X (mm)
hole_d       = 3.4;   // through-hole diameter (mm)

csk_d        = 6.5;   // countersink diameter at top surface (mm)
csk_angle    = 90;    // countersink included angle (degrees)

eps          = 0.5;   // overshoot for clean boolean cuts (mm)
$fn          = 96;    // curve resolution

// ---------------- Derived ----------------
// Depth of the cone below the top face (for a 90 deg sink this is (D-d)/2)
csk_depth    = (csk_d - hole_d) / 2 / tan(csk_angle / 2);
// Radius growth per mm of height, used to extend the cone above the surface
csk_slope    = tan(csk_angle / 2);

// ---------------- Model ----------------
difference() {
    // Flat bar, centred in X and Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thick]);

    // Screw holes, centred on the bar along X at y = 0
    for (i = [0 : hole_count - 1]) {
        x = (i - (hole_count - 1) / 2) * hole_pitch;
        translate([x, 0, 0]) {
            // Through-hole
            translate([0, 0, -eps])
                cylinder(d = hole_d, h = bar_thick + 2 * eps);

            // Countersink cone, extended eps above the top face
            translate([0, 0, bar_thick - csk_depth])
                cylinder(r1 = hole_d / 2,
                         r2 = csk_d / 2 + eps * csk_slope,
                         h  = csk_depth + eps);
        }
    }
}
