            // 90-degree countersink, extended past the top face
            // keeping the same cone angle
            translate([0, 0, bar_thick - csk_depth - 0.01])
                cylinder(d1 = hole_d - csk_slope * 0.01,
                         d2 = csk_d + csk_slope * eps,
