core_d       = 30;   // core diameter
core_h       = 30;   // core height (z = 2 to z = 32)

// Bore
bore_d       = 10;   // central bore diameter

// Derived
total_h      = flange_t + core_h + flange_t; // 34 mm
eps          = 0.5;  // cutter overshoot

difference() {
    union() {
        // Bottom flange: z = 0 to 2
        cylinder(d = flange_d, h = flange_t);

        // Core: z = 2 to 32 (slight overlap into flanges for clean union)
        translate([0, 0, flange_t - 0.01])
            cylinder(d = core_d, h = core_h + 0.02);

        // Top flange: z = 32 to 34
        translate([0, 0, flange_t + core_h])
            cylinder(d = flange_d, h = flange_t);
    }

    // Central bore through the full height
    translate([0, 0, -eps])
        cylinder(d = bore_d, h = total_h + 2 * eps);
}
